defmodule TopLevel do
  @enforce_keys [:data, :meta, :pagination]
  defstruct [:data, :meta, :pagination]

  @type t :: %__MODULE__{
          data: [Datum.t()],
          meta: Meta.t(),
          pagination: Pagination.t()
        }

  def decode_data(value) when is_list(value), do: value
  def decode_data(_), do: {:error, "Unexpected type when decoding TopLevel.data"}

  def encode_data(value) when is_list(value), do: value
  def encode_data(_), do: {:error, "Unexpected type when encoding TopLevel.data"}

  def from_map(m) do
    %TopLevel{
      data: Enum.map(m["data"], &Datum.from_map/1),
      meta: Meta.from_map(m["meta"]),
      pagination: Pagination.from_map(m["pagination"]),
    }
  end

  def from_json(json) do
    json
          |> Jason.decode!()
          |> from_map()
  end

  def to_map(struct) do
    %{
      "data" => struct.data && Enum.map(struct.data, &Datum.to_map/1),
      "meta" => Meta.to_map(struct.meta),
      "pagination" => Pagination.to_map(struct.pagination),
    }
  end

  def to_json(struct) do
    struct
          |> to_map()
          |> Jason.encode!()
  end
end
